    justify-content: space-between;
    padding: 0 16px;
    flex-shrink: 0;
    z-index: 10;
    min-width: 0;
  }

  .casca-topbar-left {
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 0;
  }

  .casca-titulo-missao {
    font-size: 14px;
    font-weight: 700;
    color: var(--casca-texto);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .casca-badge {
    font-size: 11px;
    font-weight: 700;
    padding: 2px 8px;
    border-radius: 4px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  .badge-pico { background-color: var(--casca-marca-pico); color: #FFF; }
  .badge-aha { background-color: var(--casca-marca-aha); color: #000; }
  .badge-gate { background-color: var(--casca-marca-gate); color: #000; }
  .badge-ator { background-color: #475569; color: #FFF; }

  .casca-topbar-center {
    font-size: 13px;
    color: var(--casca-texto-mutado);
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
  }

  .casca-topbar-center strong {
    color: var(--casca-texto);
  }

  .casca-topbar-right {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .casca-btn-nav {
    background: #334155;
    border: 1px solid var(--casca-borda);
    color: var(--casca-texto);
    padding: 6px 12px;
    font-size: 12px;
    font-weight: 600;
    border-radius: 4px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 4px;
    transition: background-color 0.15s;
