        texto: "O estudante é nomeado Porta-Voz oficial de dados da sua escola dentro do Unoochat. O job-to-be-done concreto exige analisar o boletim do mês, estruturar a visualização gráfica e encaminhá-la ao Comitê da Cidade acompanhada de uma Nota de Intenção pública, gerenciando com responsabilidade a cota escassa de 3 publicações oficiais.",
        fonte: "Fonte: One-Pager §4 (Etapa 1: Desafiar) e Mapa de beats."
      },
      "E2": {
        tag: "Etapa 2: Navegar",
        titulo: "Inspeção da Base e Bloqueio Documental",
        texto: "No chat privado, o Assistente de Dados apresenta a tabela com a série de 4 meses (95% para 88%). Abaixo, o componente de anexo 'Nota_Metodologica_Subprefeitura.pdf' é obrigatório: revela que a queda de 7 p.p. ocorreu exclusivamente em duas ruas antigas durante obras de tubulação, enquanto 98% da rede operou estável. O botão de avanço fica estritamente desabilitado até a abertura do anexo.",
        fonte: "Fonte: One-Pager §4 (Etapa 2: Navegar) e Não-negociável 1."
      },
      "E3": {
        tag: "Etapa 3: Decidir",
        titulo: "Parametrização, Nota de Intenção e Selo Irreversível",
        texto: "O estudante escolhe a escala definitiva (eixo Y em 0% ou 80%), redige a Nota de Intenção de 3 a 5 linhas justificando o recorte e clica em encaminhar. Um diálogo modal nativo isola o estudante no PICO de tensão: confirma que o envio gastará 1 dos 3 slots e não poderá ser editado ou excluído. Ao confirmar, o saldo cai para 2/3 e a tela migra para o feed público.",
        fonte: "Fonte: One-Pager §4 (Etapa 3: Decidir) e Não-negociável 2."
      },
      "E4": {
        tag: "Etapa 4: Resultado / Aha e Errata Técnica",
        titulo: "Contraste Social, Espelhamento e Mediação Coletiva",
        texto: "A publicação gera reações polarizadas dos cidadãos no feed (conformismo com eixo 0%; pânico coletivo com eixo 80%). Exatos 10s após, a Escola Estadual Santos Dumont posta o gráfico com a escala contrária sobre a mesma base. Ambos ficam empilhados verticalmente no feed. A interface congela compulsoriamente para o debate plenário conduzido pelo professor no quadro negro antes da liberação da 2ª Chance.",
        fonte: "Fonte: One-Pager §4 (Etapa 4: Resultado / Aha) e Não-negociáveis 3 e 4."
      },
      "E5": {
        tag: "Etapa 5: Explicar",
        titulo: "Desmontagem Matemática e Fator de Mentira",
        texto: "O Laudo de Auditoria formaliza os conceitos de truncamento de eixo, proporcionalidade geométrica e o Fator de Mentira de Tufte: a queda factual de 7 p.p. (~7,37%) virou ~47% de redução visual no eixo 80%, resultando num Lie Factor aproximado de 6,37. A régua deslizante interativa permite recalibrar o eixo e o checklist valida os 3 pilares de auditoria.",
        fonte: "Fonte: One-Pager §4 (Etapa 5: Explicar) e Descoberta Central §1."
      },
      "E6": {
        tag: "Etapa 6: Refletir e Conclusão",
        titulo: "Transferência Democrática Eleitoral e Canal B Completo",
        texto: "O estudante atua como perito independente de dados num canal público eleitoral, auditando dois gráficos conflitantes de criminalidade baseados na mesma planilha policial. Redige a Nota pericial de 3 a 5 linhas, responde às 6 perguntas da enquete diagnóstica diegética do Canal B cobrindo EM13CO12 a EM13CO26 via SurveyPoll sem gabarito exposto, escuta o podcast de recapitulação e a missão é congelada em modo leitura definitiva.",
        fonte: "Fonte: One-Pager §4 (Etapa 6: Refletir), §12a e Bloco 13 D0-3."
      }
    };

    let indiceAtual = 0;

    function renderizarTrilho() {
      const container = document.getElementById("trilho-navegacao");
      container.innerHTML = "";

      let etapaAtual = "";

      TELAS.forEach((tela, index) => {
        if (tela.etapa !== etapaAtual) {
          etapaAtual = tela.etapa;
          const titulo = document.createElement("div");
          titulo.className = "trilho-grupo-titulo";
          titulo.innerHTML = `<span>${tela.etapaNome}</span><span>${tela.etapa}</span>`;
          container.appendChild(titulo);
        }

        const item = document.createElement("button");
        item.className = "trilho-item" + (index === indiceAtual ? " ativo" : "");
        item.setAttribute("data-index", index);
        item.onclick = () => irParaIndice(index);

        let badgeMarca = "";
        if (tela.pico) badgeMarca = `<span style="font-size:9px; background:#EF4444; color:#FFF; padding:1px 4px; border-radius:2px; font-weight:800;">PICO</span>`;
        if (tela.aha) badgeMarca = `<span style="font-size:9px; background:#F59E0B; color:#000; padding:1px 4px; border-radius:2px; font-weight:800;">AHA</span>`;
        if (tela.gate) badgeMarca += ` <span style="font-size:9px; background:#10B981; color:#000; padding:1px 4px; border-radius:2px; font-weight:800;">GATE</span>`;

        item.innerHTML = `
          <div class="trilho-item-header">
            <span class="trilho-item-id">${tela.id}</span>
            <span>${badgeMarca}</span>
          </div>
          <div class="trilho-item-estado">${tela.etapaNome.startsWith("Canal B") ? tela.etapaNome + " - " + tela.estado : tela.estado}</div>
        `;
        container.appendChild(item);
      });
    }

    function atualizarTela() {
      const tela = TELAS[indiceAtual];

      // Oculta todos os quadros e ativa o correspondente
      const todosQuadros = document.querySelectorAll(".quadro-tela");
      todosQuadros.forEach((q, i) => {
        if (i === indiceAtual) {
          q.classList.add("tela-ativa");
        } else {
          q.classList.remove("tela-ativa");
        }
      });

      // Atualiza TopBar da casca
      document.getElementById("topbar-screen-id").textContent = tela.id;
      document.getElementById("topbar-estado-nome").textContent = tela.estado;
      document.getElementById("topbar-contador").textContent = `${indiceAtual + 1} de ${TELAS.length}`;

      const badgeAtor = document.getElementById("badge-ator");
      badgeAtor.textContent = tela.ator;
      badgeAtor.style.backgroundColor = tela.ator === "Professor" ? "#4F46E5" : (tela.ator === "Sistema" ? "#64748B" : "#475569");

      const badgeEtapa = document.getElementById("badge-etapa");
      badgeEtapa.textContent = `${tela.etapa}: ${tela.etapaNome}`;

      const badgeMarca = document.getElementById("badge-marca");
      if (tela.pico) {
        badgeMarca.style.display = "inline-block";
        badgeMarca.className = "casca-badge badge-pico";
        badgeMarca.textContent = "Pico de Tensão";
      } else if (tela.aha) {
        badgeMarca.style.display = "inline-block";
        badgeMarca.className = "casca-badge badge-aha";
        badgeMarca.textContent = "Momento Aha!";
      } else if (tela.gate) {
        badgeMarca.style.display = "inline-block";
        badgeMarca.className = "casca-badge badge-gate";
        badgeMarca.textContent = "Gate Síncrono";
      } else {
        badgeMarca.style.display = "none";
      }

      // Atualiza legenda da moldura
      const legendaMoldura = document.getElementById("legenda-moldura-tipo");
      legendaMoldura.textContent = tela.moldura === "mobile" 
        ? "casca de aparelho 375×812 dentro do hub" 
        : "janela do hub, 1366×768 (desktop docente)";

      // Atualiza Painel da Etapa (One-Pager)
      const etapaInfo = TEXTOS_ONE_PAGER[tela.etapa] || TEXTOS_ONE_PAGER["E1"];
      document.getElementById("painel-etapa-tag").textContent = etapaInfo.tag;
      document.getElementById("painel-etapa-titulo").textContent = etapaInfo.titulo;
      document.getElementById("painel-etapa-texto").textContent = etapaInfo.texto;
      document.getElementById("painel-meta-acao").textContent = tela.acao;
      document.getElementById("painel-meta-muda").textContent = tela.muda;
      document.getElementById("painel-meta-bncc").textContent = tela.bncc;
      document.getElementById("painel-etapa-fonte").textContent = etapaInfo.fonte;

      // Atualiza Rodapé
      document.getElementById("rodape-tela-id").textContent = `${tela.id} (${tela.estado})`;
      document.getElementById("rodape-acao").textContent = tela.acao;
      document.getElementById("rodape-muda").textContent = tela.muda;

      // Atualiza botões anterior / próxima
      document.getElementById("btn-ant").disabled = indiceAtual === 0;
      document.getElementById("btn-prox").disabled = indiceAtual === TELAS.length - 1;

      // Atualiza seleção no trilho
      const itensTrilho = document.querySelectorAll(".trilho-item");
      itensTrilho.forEach((it, idx) => {
        if (idx === indiceAtual) {
          it.classList.add("ativo");
          it.scrollIntoView({ block: "nearest", behavior: "smooth" });
        } else {
          it.classList.remove("ativo");
        }
      });
    }

    function irParaIndice(novoIndice) {
      if (novoIndice >= 0 && novoIndice < TELAS.length) {
        indiceAtual = novoIndice;
        atualizarTela();
      }
    }

    // CONTROLES DE NAVEGAÇÃO
    document.getElementById("btn-ant").onclick = () => irParaIndice(indiceAtual - 1);
    document.getElementById("btn-prox").onclick = () => irParaIndice(indiceAtual + 1);

    window.addEventListener("keydown", (e) => {
      if (e.key === "ArrowLeft") {
        irParaIndice(indiceAtual - 1);
      } else if (e.key === "ArrowRight") {
        irParaIndice(indiceAtual + 1);
      }
    });

    // INICIALIZAÇÃO
    renderizarTrilho();
    atualizarTela();
  </script>
</body>
</html>
